// Cabinet admin controls -- renders documentation/CONTENT-INVENTORY.md as
// HTML, read straight off this machine's disk (via the same static-file
// fallback tools/admin-controls.js already serves the whole repo through),
// so it always shows the freshly-built local copy rather than whatever's
// last pushed to GitHub. Small hand-rolled markdown-to-HTML converter
// instead of a library, matching this UI's zero-dependency convention
// (home.js/cabinet-editor.js/now-editor.js) -- CONTENT-INVENTORY.md is
// itself auto-generated by tools/generate_sitemap.py, so its shape is
// known and stable (h1/h2, one italic intro line, GFM tables, a flat
// bullet list): headers, bold/italic/code/links, bullet lists, and GFM
// tables are the only constructs it ever needs to handle.

const DOC_PATH = "/documentation/CONTENT-INVENTORY.md";

function escapeHtml(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function inline(text) {
  let s = escapeHtml(text);
  s = s.replace(/`([^`]+)`/g, (_, code) => `<code>${code}</code>`);
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, label, url) => `<a href="${url}" target="_blank" rel="noopener">${label}</a>`);
  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/(^|[^\w])_([^_]+)_(?=[^\w]|$)/g, "$1<em>$2</em>");
  return s;
}

function splitTableRow(line) {
  let t = line.trim();
  if (t.startsWith("|")) t = t.slice(1);
  if (t.endsWith("|")) t = t.slice(0, -1);
  return t.split("|").map(cell => cell.trim());
}

const TABLE_SEPARATOR_RE = /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/;

function renderMarkdown(md) {
  const lines = md.replace(/\r\n/g, "\n").split("\n");
  let html = "";
  let paragraph = [];
  let i = 0;

  function flushParagraph() {
    if (paragraph.length) {
      html += `<p>${inline(paragraph.join(" "))}</p>\n`;
      paragraph = [];
    }
  }

  while (i < lines.length) {
    const line = lines[i];

    if (/^\s*$/.test(line)) { flushParagraph(); i++; continue; }

    const heading = line.match(/^(#{1,6})\s+(.*)$/);
    if (heading) {
      flushParagraph();
      const level = heading[1].length;
      html += `<h${level}>${inline(heading[2])}</h${level}>\n`;
      i++; continue;
    }

    if (/^\s*-\s+/.test(line)) {
      flushParagraph();
      html += "<ul>\n";
      while (i < lines.length && /^\s*-\s+/.test(lines[i])) {
        html += `<li>${inline(lines[i].replace(/^\s*-\s+/, ""))}</li>\n`;
        i++;
      }
      html += "</ul>\n";
      continue;
    }

    if (line.includes("|") && i + 1 < lines.length && TABLE_SEPARATOR_RE.test(lines[i + 1])) {
      flushParagraph();
      const headerCells = splitTableRow(line);
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].includes("|") && lines[i].trim() !== "") {
        rows.push(splitTableRow(lines[i]));
        i++;
      }
      html += '<div class="md-table-wrap"><table class="md-table"><thead><tr>' +
        headerCells.map(c => `<th>${inline(c)}</th>`).join("") +
        "</tr></thead><tbody>" +
        rows.map(r => "<tr>" + r.map(c => `<td>${inline(c)}</td>`).join("") + "</tr>").join("\n") +
        "</tbody></table></div>\n";
      continue;
    }

    paragraph.push(line.trim());
    i++;
  }
  flushParagraph();
  return html;
}

async function loadInventory() {
  const view = document.getElementById("view");
  const status = document.getElementById("status");
  status.textContent = "Loading...";
  status.className = "md-status";
  try {
    const res = await fetch(`${DOC_PATH}?t=${Date.now()}`, { cache: "no-store" });
    if (!res.ok) {
      status.textContent = res.status === 404
        ? "CONTENT-INVENTORY.md doesn't exist yet on disk -- click \"Regenerate & reload\" to build it."
        : `Fetch failed: ${res.status}`;
      status.classList.add("error");
      view.innerHTML = "";
      return;
    }
    const md = await res.text();
    view.innerHTML = renderMarkdown(md);
    status.textContent = "";
  } catch (err) {
    status.textContent = `Couldn't reach the admin server (${err}) -- is this page open via node tools/admin-controls.js, not a static file server?`;
    status.classList.add("error");
  }
}

document.getElementById("regen-btn").addEventListener("click", async () => {
  const btn = document.getElementById("regen-btn");
  const status = document.getElementById("status");
  btn.disabled = true;
  btn.textContent = "Regenerating...";
  status.textContent = "";
  status.className = "md-status";
  try {
    const res = await fetch("/api/run/sitemap", { method: "POST" });
    const body = await res.json();
    if (!body.ok) {
      status.textContent = `generate_sitemap.py failed: ${body.error}`;
      status.classList.add("error");
    }
  } catch (err) {
    status.textContent = `Couldn't reach the admin server (${err}).`;
    status.classList.add("error");
  } finally {
    btn.disabled = false;
    btn.textContent = "Regenerate & reload";
  }
  await loadInventory();
});

loadInventory();
